entries[154167] = { ["name"] = "Drums of the Maelstrom", ["text"] = "Use: Increases Haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism or Time Warp again for 10 min.\n\nDoes not does affect allies above level 50. (2 Min Cooldown)\nSell Price:" }
