entries[154172] = { ["name"] = "Aman'Thul's Vision", ["text"] = "Binds when picked up\nUnique-Equipped: Path of the Titans (1)\nTrinket\n+ 6 Critical Strike\n+ 6 Haste\n+ 6 Versatility\n+ 6 Mastery\nEquip: Your spells and abilities have a chance to grant you 9 Speed, Avoidance, and Leech for 12 sec.\n\nAman'Thul's Grandeur\nWhen empowered by the Pantheon, your Intellect is increased by 6 for 15 sec.\nSell Price:" }
entries[154173] = { ["name"] = "Aggramar's Conviction", ["text"] = "Binds when picked up\nUnique-Equipped: Path of the Titans (1)\nTrinket\n+6 [Agility or Strength]\nEquip: Taking damage has a chance to increase your Versatility by 27 for 14 sec.\n\nAggramar's Fortitude\nWhen empowered by the Pantheon, your maximum health is increased by 94 for 15 sec, and you are healed for 988 .\nSell Price:" }
entries[154174] = { ["name"] = "Golganneth's Vitality", ["text"] = "Binds when picked up\nUnique-Equipped: Path of the Titans (1)\nTrinket\n+6 Agility\nEquip: Your damaging abilities have a chance to create a Ravaging Storm at your target's location, inflicting ( 10 * 6) Nature damage split among all enemies within 6 yds over 6 sec.\n\nGolganneth's Thunderous Wrath\nWhen empowered by the Pantheon, your autoattacks cause an explosion of lightning dealing [ 1 * (Mainhand weapon min base speed) * 5 ] Nature damage to all enemies within 8 yds of the target. Lasts 15 sec.\nSell Price:" }
entries[154175] = { ["name"] = "Eonar's Compassion", ["text"] = "Binds when picked up\nUnique-Equipped: Path of the Titans (1)\nTrinket\n+6 Intellect\nEquip: Your healing effects have a chance to grow an Emerald Blossom nearby, which heals a random injured ally for 16 every 2 sec. Lasts 12 sec.\n\nEonar's Verdant Embrace\nWhen empowered by the Pantheon, your next 4 direct healing spells grant the target a shield that prevents 24 damage for 30 sec.\nSell Price:" }
entries[154176] = { ["name"] = "Khaz'goroth's Courage", ["text"] = "Binds when picked up\nUnique-Equipped: Path of the Titans (1)\nTrinket\n+6 Strength\nEquip: Your damaging attacks have a chance to make your weapon glow hot with the fire of Khaz'goroth's forge, causing your autoattacks to do ( 1 * Mainhand weapon min base speed * 8 ) additional Fire damage for 12 sec.\n\nKhaz'goroth's Shaping\nWhen empowered by the Pantheon, your Critical Strike, Haste, Mastery, or Versatility is increased by 26 for 15 sec. Khaz'goroth always empowers your highest stat.\nSell Price:" }
entries[154177] = { ["name"] = "Norgannon's Prowess", ["text"] = "Binds when picked up\nUnique-Equipped: Path of the Titans (1)\nTrinket\n+ 8 Mastery\nEquip: Your damaging spells have a chance to increase your Intellect by 22 for 12 sec.\n\nNorgannon's Command\nWhen empowered by the Pantheon, you gain 6 charges of Norgannon's Command for 15 sec. Your damaging spells expend a charge to inflict an additional 13 damage to the target, from a random school of magic.\nSell Price:" }
